import{_ as t,o as n,c as i,a3 as d}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Dokumente einrichten","description":"Persönliche Unterlagen und Unternehmensdokumente in der App – mit Suche, Kategorien, Fristen und Kenntnisnahme, wahlweise mit Unterschrift oder je Person zugewiesen.","frontmatter":{"title":"Dokumente einrichten","description":"Persönliche Unterlagen und Unternehmensdokumente in der App – mit Suche, Kategorien, Fristen und Kenntnisnahme, wahlweise mit Unterschrift oder je Person zugewiesen."},"headers":[],"relativePath":"apptiveteams/dokumente.md","filePath":"apptiveteams/dokumente.md","lastUpdated":1789044113000}'),r={name:"apptiveteams/dokumente.md"};function a(s,e,l,o,h,c){return n(),i("div",null,[...e[0]||(e[0]=[d(`<h1 id="dokumente-einrichten" tabindex="-1">Dokumente einrichten <a class="header-anchor" href="#dokumente-einrichten" aria-label="Permalink to &quot;Dokumente einrichten&quot;">​</a></h1><p>Ein Tab vom Typ <code>Documents</code> zeigt Dokumente aus einem Grid in der App: PDFs und andere Dateien mit Titel, Kategorie, Fassung und Gültigkeit, dazu eine Suche und Filter nach Kategorie. Dokumente, die eine <strong>Kenntnisnahme</strong> verlangen, tragen eine Frist; die Person bestätigt in der App, wahlweise mit Unterschrift, und Sie sehen im Grid, wer wann bestätigt hat. Wollen Sie sicher sein, dass <strong>jeder</strong> es gelesen hat, legen Sie die Kenntnisnahmen je Person vorab an – von Hand oder per Flow – dann steht auch im Grid, wer noch nicht.</p><p>Der Tab zeigt immer <strong>eine</strong> Quelle. Für die zwei üblichen Bereiche legen Sie deshalb <strong>zwei Tabs</strong> an:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Inhalt</th><th>Quelle</th></tr></thead><tbody><tr><td><strong>Meine Dokumente</strong></td><td>Gehaltsabrechnungen, Bescheinigungen, Vertragsunterlagen – nur für die jeweilige Person sichtbar</td><td>eine Ansicht, die auf die angemeldete Person gefiltert ist</td></tr><tr><td><strong>Unternehmen</strong></td><td>Richtlinien, Handbuch, Vorlagen – für alle oder eine Zielgruppe</td><td>ein Grid oder eine Ansicht</td></tr></tbody></table><p>Beide Tabs verwenden dasselbe Feld-Schema. Ob ein Grid persönliche Unterlagen oder Unternehmensdokumente enthält, entscheidet allein, welche Felder Sie pflegen.</p><p>Die App legt pro Tab eine <strong>Offline-Kopie</strong> der Liste auf dem Gerät an; die Dateien selbst werden beim Öffnen geladen und brauchen eine Verbindung. Beim Abmelden werden alle Kopien gelöscht.</p><h2 id="die-tabs-zeile" tabindex="-1">Die Tabs-Zeile <a class="header-anchor" href="#die-tabs-zeile" aria-label="Permalink to &quot;Die Tabs-Zeile&quot;">​</a></h2><p>Im Grid <code>tabs</code> des Team Space ergänzen Sie je Bereich eine Zeile:</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Wert</th></tr></thead><tbody><tr><td><code>title</code></td><td>zum Beispiel „Meine Dokumente“ oder „Unternehmen“</td></tr><tr><td><code>icon</code></td><td>einfarbiges SVG</td></tr><tr><td><code>type</code></td><td><code>Documents</code></td></tr><tr><td><code>gridUri</code></td><td>Verknüpfung auf das Grid oder eine Ansicht darauf</td></tr><tr><td><code>uri</code></td><td>alternativ: Link einer geteilten Ansicht</td></tr></tbody></table><p>Sie brauchen <strong>eines</strong> der beiden Felder; sind beide gesetzt, gilt <code>gridUri</code>. Liegen die Dokumente in einem Space, auf den die Belegschaft keinen Zugriff hat, teilen Sie dort eine Ansicht per Link und tragen den Link in <code>uri</code> ein. Ein weiteres Feld im Tabs-Grid ist nicht nötig. → <a href="/apptiveteams/tabs">Tabs einrichten</a></p><h2 id="das-dokumenten-grid" tabindex="-1">Das Dokumenten-Grid <a class="header-anchor" href="#das-dokumenten-grid" aria-label="Permalink to &quot;Das Dokumenten-Grid&quot;">​</a></h2><p>Nur <code>file</code> ist Pflicht. Alles andere erscheint, wenn es da ist. Die Namen der Felder sind frei, die <strong>Keys</strong> müssen genau stimmen. → <a href="/apptiveteams/team-space#keys-wie-die-app-ihre-grids-findet">Keys vergeben</a></p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>file</code></td><td>Anhang</td><td>ja</td><td>Die Datei; die erste wird verwendet. Zeilen ohne Datei erscheinen nicht</td></tr><tr><td><code>title</code></td><td>Text</td><td>nein</td><td>Titel. Fehlt er, heißt die Zeile „Dokumenttyp Zeitraum“, sonst wie die Datei</td></tr><tr><td><code>recipient</code></td><td>Benutzer</td><td>für persönliche Unterlagen</td><td>Der Empfänger; danach filtert die Ansicht, siehe unten</td></tr><tr><td><code>category</code></td><td>Einzelauswahl oder Text</td><td>nein</td><td>Kategorie, zum Beispiel „Arbeitssicherheit“. Gibt es Kategorien, gliedern sie die Liste und bilden die Filter; sonst gliedert das Jahr</td></tr><tr><td><code>type</code></td><td>Einzelauswahl oder Text</td><td>nein</td><td>Dokumenttyp, zum Beispiel „Gehaltsabrechnung“</td></tr><tr><td><code>period</code></td><td>Datum oder Text</td><td>nein</td><td>Zeitraum: als Datum der Monatserste (die App zeigt „August 2026“), als Text zum Beispiel „2025“ für ein Jahresdokument</td></tr><tr><td><code>version</code></td><td>Text</td><td>nein</td><td>Fassung, zum Beispiel „2.1“</td></tr><tr><td><code>publishedAt</code></td><td>Datum</td><td>nein</td><td>Veröffentlichung oder Bereitstellung</td></tr><tr><td><code>validFrom</code>, <code>validUntil</code></td><td>Datum</td><td>nein</td><td>Gültigkeit; nach <code>validUntil</code> zeigt die App „Abgelaufen“</td></tr><tr><td><code>owner</code></td><td>Text oder Benutzer</td><td>nein</td><td>Verantwortliche Person oder Abteilung</td></tr><tr><td><code>audience</code></td><td>Mehrfachauswahl oder Text</td><td>nein</td><td>Zielgruppe – nur zur Anzeige, siehe Hinweis</td></tr><tr><td><code>description</code></td><td>Text</td><td>nein</td><td>Kurzbeschreibung</td></tr><tr><td><code>acknowledge</code></td><td>Häkchen</td><td>nein</td><td>Kenntnisnahme verlangt</td></tr><tr><td><code>acknowledgeUntil</code></td><td>Datum</td><td>nein</td><td>Frist für die Kenntnisnahme</td></tr><tr><td><code>acknowledgeForm</code></td><td>Weblink</td><td>für Kenntnisnahmen in Selbstbedienung</td><td>Link des Formulars, das eine Kenntnisnahme anlegt. Bei zugewiesenen Kenntnisnahmen <strong>leer lassen</strong>, siehe unten</td></tr><tr><td><code>acknowledgements</code></td><td>Verknüpfung oder Mehrfach-Verknüpfung</td><td>für Kenntnisnahmen</td><td>Zeigt auf die gefilterte Ansicht der Kenntnisnahmen; der Zellwert bleibt leer</td></tr><tr><td><code>active</code></td><td>Häkchen</td><td>nein</td><td>Nicht angehakte Zeilen werden ausgeblendet. Fehlt das Feld, sind alle sichtbar</td></tr></tbody></table><p>Ein Dokument ohne Fassung, Gültigkeit, Beschreibung, Verantwortliche, Zielgruppe und Kenntnisnahme – eine Gehaltsabrechnung etwa – öffnet beim Antippen direkt die Datei. Alle anderen führen auf eine Detailseite.</p><div class="warning custom-block"><p class="custom-block-title"><code>audience</code> ist keine Berechtigung</p><p>Wer ein Dokument sieht, entscheidet die Ansicht, auf die der Tab zeigt – nicht der Wert in <code>audience</code>. Sollen Richtlinien nur einen Standort erreichen, legen Sie je Standort eine gefilterte Ansicht und einen Tab an.</p></div><h2 id="personliche-unterlagen-die-ansicht-filtert" tabindex="-1">Persönliche Unterlagen: die Ansicht filtert <a class="header-anchor" href="#personliche-unterlagen-die-ansicht-filtert" aria-label="Permalink to &quot;Persönliche Unterlagen: die Ansicht filtert&quot;">​</a></h2><p>Für „Meine Dokumente“ zeigt der Tab nicht auf das Grid, sondern auf eine <strong>Ansicht</strong> mit dem Filter <strong>Empfänger ist die angemeldete Person</strong> (Feld <code>recipient</code>). Der Filter wird auf dem Server ausgewertet: Jede Person bekommt über dieselbe Adresse nur ihre eigenen Zeilen. Blenden Sie <code>recipient</code> in der Ansicht ein.</p><div class="warning custom-block"><p class="custom-block-title">Die App verweigert eine ungefilterte Ansicht</p><p>Liefert eine Ansicht mit dem Feld <code>recipient</code> Zeilen mehrerer Personen, zeigt der Tab <strong>keine</strong> Dokumente, sondern einen Hinweis auf den fehlenden Filter. Das schützt vor dem häufigsten Fehler – einem Tab, der auf das Grid statt auf die Ansicht zeigt. Es ersetzt den Filter nicht: Ohne ihn wären die Zeilen über die API weiterhin lesbar.</p></div><p><code>recipient</code> ist ein <strong>Benutzer</strong>-Feld, nicht „Erstellt von“: Angelegt wird eine Gehaltsabrechnung von der Personalabteilung oder einem Import, sehen darf sie der Empfänger.</p><h2 id="kenntnisnahme" tabindex="-1">Kenntnisnahme <a class="header-anchor" href="#kenntnisnahme" aria-label="Permalink to &quot;Kenntnisnahme&quot;">​</a></h2><p>Soll ein Dokument bestätigt werden, setzen Sie <code>acknowledge</code> und eine Frist in <code>acknowledgeUntil</code>. Die Bestätigung selbst ist eine Zeile in einem zweiten Grid, dem <strong>Kenntnisnahmen-Grid</strong>. Dafür gibt es zwei Wege:</p><table tabindex="0"><thead><tr><th></th><th>Selbstbedienung</th><th>Zuweisung</th></tr></thead><tbody><tr><td><strong>Wann entsteht die Zeile</strong></td><td>wenn die Person bestätigt</td><td>vorab, je Person und Fassung – von Hand oder per Flow</td></tr><tr><td><strong>Offen heißt</strong></td><td>es gibt noch keine Zeile</td><td>die Zeile ist da, das Häkchen <code>done</code> fehlt</td></tr><tr><td><strong>Wer noch nicht</strong></td><td>die Differenz zur Belegschaft</td><td>steht im Grid: alle Zeilen ohne <code>done</code></td></tr><tr><td><strong>Aufwand</strong></td><td>zwei Spalten, ein Formular, kein Flow</td><td>dazu drei Felder; die Zeilen legen Sie bei wenigen Personen von Hand an, sonst per Flow</td></tr><tr><td><strong>Passt für</strong></td><td>Handbuch, Richtlinien, Speiseplan</td><td>Unterweisungen, Datenschutz – alles, was Sie nachweisen müssen</td></tr></tbody></table><p><strong>Welcher Weg gilt, entscheidet das Kenntnisnahmen-Grid selbst:</strong> Hat es ein Benutzer-Feld <code>recipient</code>, weist es zu; sonst ist es Selbstbedienung. In der App stellen Sie nichts ein. Beide Wege lassen sich im selben Dokumenten-Grid mischen, siehe <a href="#beides-nebeneinander">Beides nebeneinander</a>.</p><h3 id="selbstbedienung-das-formular-legt-die-zeile-an" tabindex="-1">Selbstbedienung: das Formular legt die Zeile an <a class="header-anchor" href="#selbstbedienung-das-formular-legt-die-zeile-an" aria-label="Permalink to &quot;Selbstbedienung: das Formular legt die Zeile an&quot;">​</a></h3><p>Die Person bestätigt in der App, und dabei entsteht die Zeile – „Erstellt von“ und „Erstellt am“ setzt ApptiveGrid, die App kann keine Kenntnisnahme für jemand anderen erzeugen.</p><h4 id="_1-das-kenntnisnahmen-grid" tabindex="-1">1. Das Kenntnisnahmen-Grid <a class="header-anchor" href="#_1-das-kenntnisnahmen-grid" aria-label="Permalink to &quot;1. Das Kenntnisnahmen-Grid&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>document</code></td><td>Verknüpfung auf das Dokumenten-Grid</td><td>ja</td><td>Das bestätigte Dokument</td></tr><tr><td><em>(frei)</em></td><td>Erstellt von</td><td>ja</td><td>Wer bestätigt hat; wird automatisch gesetzt</td></tr><tr><td><code>version</code></td><td>Text</td><td>nein</td><td>Die bestätigte Fassung; die App trägt sie ein</td></tr><tr><td><code>acknowledgedAt</code></td><td>Datum und Uhrzeit</td><td>nein</td><td>Zeitpunkt; die App trägt ihn ein. Fehlt das Feld, gilt „Erstellt am“</td></tr><tr><td><code>signature</code></td><td>Unterschrift</td><td>nein</td><td>Steht das Feld im Formular, verlangt die Kenntnisnahme eine Unterschrift</td></tr></tbody></table><h4 id="_2-die-ansicht" tabindex="-1">2. Die Ansicht <a class="header-anchor" href="#_2-die-ansicht" aria-label="Permalink to &quot;2. Die Ansicht&quot;">​</a></h4><p>Legen Sie auf dem Kenntnisnahmen-Grid eine Ansicht mit dem Filter <strong>Erstellt von ist angemeldeter Benutzer</strong> an und blenden Sie alle Felder ein. Aus dieser Ansicht liest die App, was die Person schon bestätigt hat.</p><h4 id="_3-das-formular" tabindex="-1">3. Das Formular <a class="header-anchor" href="#_3-das-formular" aria-label="Permalink to &quot;3. Das Formular&quot;">​</a></h4><p>Erstellen Sie ein Formular auf dem Kenntnisnahmen-Grid mit dem Feld <code>document</code>, optional <code>version</code> und <code>acknowledgedAt</code>. Soll unterschrieben werden, nehmen Sie <code>signature</code> dazu. Teilen Sie das Formular mit der Beschränkung <strong>Jeder registrierte Benutzer</strong>, damit „Erstellt von“ die Person ist. → <a href="/formulare/formular-teilen">Formular teilen</a></p><h4 id="_4-zwei-spalten-im-dokumenten-grid" tabindex="-1">4. Zwei Spalten im Dokumenten-Grid <a class="header-anchor" href="#_4-zwei-spalten-im-dokumenten-grid" aria-label="Permalink to &quot;4. Zwei Spalten im Dokumenten-Grid&quot;">​</a></h4><ul><li><code>acknowledgeForm</code> (Weblink): der Formular-Link. Er darf für alle Zeilen derselbe sein – die App trägt das Dokument ein – oder je Zeile ein vorausgefüllter Link.</li><li><code>acknowledgements</code> (Verknüpfung oder Mehrfach-Verknüpfung): zeigt auf die <strong>Ansicht</strong> aus Schritt 2, nicht auf das Grid. Der Zellwert bleibt leer; die App braucht nur die Adresse, die in der Spalte steckt. Blenden Sie die Spalte in der Ansicht des Tabs ein.</li></ul><p>Ein Flow ist nicht nötig.</p><div class="tip custom-block"><p class="custom-block-title">Unterschrift</p><p>Mit dem Feld <code>signature</code> im Formular zeigt die App statt des Bestätigen-Knopfs das Formular mit Unterschriftenfeld. Ohne das Feld genügt ein Tipp. So entscheiden Sie je Formular – und damit je Dokument –, ob eine Unterschrift nötig ist. Das gilt für beide Wege.</p></div><h3 id="zuweisung-die-zeilen-sind-vorher-da" tabindex="-1">Zuweisung: die Zeilen sind vorher da <a class="header-anchor" href="#zuweisung-die-zeilen-sind-vorher-da" aria-label="Permalink to &quot;Zuweisung: die Zeilen sind vorher da&quot;">​</a></h3><p>Wer nachweisen muss, dass jeder gelesen hat, dreht die Reihenfolge um: Die Zeile ist da, bevor jemand etwas getan hat, und wird abgehakt. Wer sie anlegt – Sie von Hand oder ein Flow – ist der App gleich. Die Person sieht in der App dieselbe Karte und denselben Knopf; anders ist nur, was dahinter passiert.</p><h4 id="_1-drei-felder-mehr-im-kenntnisnahmen-grid" tabindex="-1">1. Drei Felder mehr im Kenntnisnahmen-Grid <a class="header-anchor" href="#_1-drei-felder-mehr-im-kenntnisnahmen-grid" aria-label="Permalink to &quot;1. Drei Felder mehr im Kenntnisnahmen-Grid&quot;">​</a></h4><p>Zusätzlich zu <code>document</code> und den optionalen Feldern von oben:</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>recipient</code></td><td>Benutzer</td><td>ja</td><td>Für wen die Zeile angelegt wurde. <strong>Dieses Feld schaltet die Zuweisung ein</strong></td></tr><tr><td><code>done</code></td><td>Häkchen</td><td>ja</td><td>Erledigt. Die Zeile wird ohne Häkchen angelegt, die App setzt es</td></tr><tr><td><code>editLink</code></td><td>Weblink</td><td>ja</td><td>Der Bearbeitungslink genau dieser Zeile – aus dem Freigabedialog der Zeile oder vom Flow</td></tr><tr><td><code>dueDate</code></td><td>Datum</td><td>nein</td><td>Eine eigene Frist für diese Person. Geht <code>acknowledgeUntil</code> des Dokuments vor</td></tr></tbody></table><p>Pflegen Sie <code>version</code> in jeder Zeile. Eine Zeile ohne Fassung gilt für das Dokument als Ganzes – dann wäre Fassung 2.2 durch die Bestätigung von 2.1 abgedeckt.</p><p>Ein Feld „Erstellt von“ brauchen Sie hier nicht; es stört aber auch nicht.</p><h4 id="_2-die-ansicht-1" tabindex="-1">2. Die Ansicht <a class="header-anchor" href="#_2-die-ansicht-1" aria-label="Permalink to &quot;2. Die Ansicht&quot;">​</a></h4><p>Der Filter der Ansicht lautet jetzt <strong>Empfänger ist angemeldeter Benutzer</strong> (Feld <code>recipient</code>) statt „Erstellt von“. Alle Felder einblenden, <code>editLink</code> eingeschlossen. Die Spalte <code>acknowledgements</code> im Dokumenten-Grid zeigt wie bei der Selbstbedienung auf diese Ansicht.</p><div class="warning custom-block"><p class="custom-block-title">Der Bearbeitungslink öffnet genau diese Zeile</p><p>Wer den Link hat, kann die Zeile bearbeiten – ohne weitere Prüfung, wer die Person ist. Er darf deshalb nur die Person erreichen, der die Zeile gehört. Genau das leistet der Filter der Ansicht: Jede Person bekommt ausschließlich ihre eigenen Zeilen und damit nur ihre eigenen Links. Blenden Sie <code>editLink</code> in keiner anderen geteilten Ansicht ein. → <a href="/formulare/eintraege-bearbeiten#sicherheit">Einträge per Formular bearbeiten</a></p></div><h4 id="_3-das-formular-1" tabindex="-1">3. Das Formular <a class="header-anchor" href="#_3-das-formular-1" aria-label="Permalink to &quot;3. Das Formular&quot;">​</a></h4><p>Ein Formular auf dem Kenntnisnahmen-Grid mit dem Feld <code>done</code>, optional <code>acknowledgedAt</code> und <code>signature</code>. <code>document</code> braucht es nicht – das steht in der Zeile schon. Dieses Formular öffnet der Bearbeitungslink; die App setzt <code>done</code> und sendet ab. Mit <code>signature</code> zeigt sie das Formular an, das Häkchen bereits gesetzt.</p><h4 id="_4-die-zeilen-anlegen-von-hand-oder-per-flow" tabindex="-1">4. Die Zeilen anlegen: von Hand oder per Flow <a class="header-anchor" href="#_4-die-zeilen-anlegen-von-hand-oder-per-flow" aria-label="Permalink to &quot;4. Die Zeilen anlegen: von Hand oder per Flow&quot;">​</a></h4><p>Je Person und Fassung eine Zeile: <code>recipient</code>, <code>document</code>, <code>version</code>, bei Bedarf <code>dueDate</code>; <code>done</code> bleibt leer. Dann der Bearbeitungslink der Zeile nach <code>editLink</code>.</p><p><strong>Von Hand</strong> reicht für ein kleines Team oder eine einzelne Unterweisung: Zeilen anlegen, je Zeile über den Freigabedialog <strong>Zur Bearbeitung teilen</strong> den Link mit dem Formular aus Schritt 3 erzeugen und in <code>editLink</code> eintragen. → <a href="/formulare/eintraege-bearbeiten#einen-eintrag-zur-bearbeitung-teilen">Einen Eintrag zur Bearbeitung teilen</a></p><p><strong>Per Flow</strong>, wenn es viele sind oder regelmäßig neue Fassungen kommen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag wurde geändert   (Dokumenten-Grid, z.B. \`publishedAt\` gesetzt)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Alle Einträge laden                → die Mitarbeitenden, ggf. gefiltert auf die Zielgruppe</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                           → für jede Person:</span></span>
<span class="line"><span>   ├ Eintrag erstellen             → Kenntnisnahmen-Grid: recipient, document, version, dueDate; done leer</span></span>
<span class="line"><span>   ├ Vorausgefüllter Formularlink  → Formular aus Schritt 3 für die neue Zeile</span></span>
<span class="line"><span>   └ Eintrag aktualisieren         → den Link in editLink schreiben</span></span></code></pre></div><p>Bis eine Zeile angelegt und ihr Link geschrieben ist, zeigt die App auf der Detailseite „Die Bestätigung wird gerade vorbereitet“. Bei einer neuen Fassung legen Sie neue Zeilen an – oder der Flow läuft erneut; die alten passen nicht mehr zur neuen Fassung, das Dokument ist wieder offen.</p><p>→ <a href="/flows/aktionen#eintrag-erstellen">Aktionen</a> · <a href="/flows/router-und-parallel">Parallel</a> · <a href="/flows/aktionen#vorausgefullter-formularlink">Vorausgefüllter Formularlink</a> · <a href="/flows/trigger#eintrag-wurde-geandert">Trigger</a></p><h4 id="_5-acknowledgeform-leeren" tabindex="-1">5. <code>acknowledgeForm</code> leeren <a class="header-anchor" href="#_5-acknowledgeform-leeren" aria-label="Permalink to &quot;5. \`acknowledgeForm\` leeren&quot;">​</a></h4><p>Lassen Sie <code>acknowledgeForm</code> bei den Dokumenten leer, die zugewiesen werden. Ein Dokument, das den Link noch trägt, bleibt Selbstbedienung – siehe den nächsten Abschnitt.</p><h3 id="beides-nebeneinander" tabindex="-1">Beides nebeneinander <a class="header-anchor" href="#beides-nebeneinander" aria-label="Permalink to &quot;Beides nebeneinander&quot;">​</a></h3><p>Die Wahl fällt <strong>je Dokument</strong>, nicht je Grid: Eine Zuweisung betrifft ein Dokument, nicht das nächste. In einem Dokumenten-Grid, dessen Kenntnisnahmen-Grid zuweist, gilt für jede Zeile:</p><table tabindex="0"><thead><tr><th>Lage</th><th>Was die App tut</th></tr></thead><tbody><tr><td>Zugewiesene Zeile mit Bearbeitungslink</td><td>Bestätigen-Knopf; abgehakt wird diese Zeile</td></tr><tr><td>Zugewiesene Zeile, Link fehlt noch</td><td>„Die Bestätigung wird gerade vorbereitet“ – <code>editLink</code> ist noch leer</td></tr><tr><td>Keine Zeile, Dokument hat <code>acknowledgeForm</code></td><td>Selbstbedienung wie oben; die neue Zeile entsteht mit gesetztem <code>done</code></td></tr><tr><td>Keine Zeile, kein <code>acknowledgeForm</code></td><td>„Die Bestätigung wird gerade vorbereitet“</td></tr></tbody></table><p>So weisen Sie die Unterweisungen zu und lassen sich den Speiseplan weiter selbst abhaken – im selben Grid, mit demselben Kenntnisnahmen-Grid.</p><div class="warning custom-block"><p class="custom-block-title">Beim Umstellen <code>acknowledgeForm</code> leeren</p><p>Wechseln Sie von Selbstbedienung auf Zuweisung, steht <code>acknowledgeForm</code> noch in jeder Zeile. Für diese Dokumente bleibt es bei Selbstbedienung, obwohl schon Zeilen angelegt sind – und die Person legt beim Bestätigen eine zweite Zeile neben die zugewiesene. Die App kann das nicht unterscheiden; sie nennt solche Dokumente nur im Entwickler-Log. Leeren Sie die Spalte, wo zugewiesen wird.</p></div><h2 id="so-arbeitet-die-app" tabindex="-1">So arbeitet die App <a class="header-anchor" href="#so-arbeitet-die-app" aria-label="Permalink to &quot;So arbeitet die App&quot;">​</a></h2><ul><li>Beim Öffnen des Tabs lädt die App die Liste und speichert sie als Offline-Kopie pro Tab. Ohne Verbindung zeigt sie den zuletzt geladenen Stand; die Dateien brauchen eine Verbindung.</li><li>Gibt es Kategorien, gliedert die Liste danach, alphabetisch. Sonst gliedert sie nach Jahr, das neueste oben – für Abrechnungen und Bescheinigungen.</li><li>Über der Liste nennt ein Hinweis die offenen Kenntnisnahmen mit den nächsten Fristen; überfällige werden rot markiert.</li><li>Eine neue Fassung eines Dokuments gilt wieder als „neu“ und ist wieder zu bestätigen, wenn die Kenntnisnahme eine Fassung nennt.</li><li>Bei zugewiesenen Kenntnisnahmen zeigt die App je Person nur die eigenen Zeilen. Wer noch nicht bestätigt hat, sehen Sie im Kenntnisnahmen-Grid, nicht in der App.</li><li>Beim Abmelden werden die Kopien aller Teams vom Gerät gelöscht.</li></ul><h2 id="wenn-etwas-fehlt" tabindex="-1">Wenn etwas fehlt <a class="header-anchor" href="#wenn-etwas-fehlt" aria-label="Permalink to &quot;Wenn etwas fehlt&quot;">​</a></h2><p>Die App nennt fehlende Feld-Keys direkt im Tab, zusammen mit den Feldern, die die Quelle tatsächlich liefert.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td>Kein Tab in der App</td><td>Tabs-Zeile unvollständig: <code>type</code>, <code>gridUri</code>/<code>uri</code> oder das Icon fehlt</td></tr><tr><td>„Fehlende Feld-Keys: file“</td><td>Das Anhang-Feld hat keinen Key <code>file</code></td></tr><tr><td>Hinweis „nicht auf die angemeldete Person gefiltert“</td><td>Der Tab zeigt auf das Grid der persönlichen Unterlagen statt auf die gefilterte Ansicht</td></tr><tr><td>Bestätigen-Knopf fehlt, „keine Kenntnisnahme eingerichtet“</td><td>Selbstbedienung: <code>acknowledgeForm</code> ist leer</td></tr><tr><td>„Die Bestätigung wird gerade vorbereitet“ bleibt stehen</td><td>Zuweisung: für diese Person und Fassung gibt es keine Zeile, oder <code>editLink</code> ist leer – bei einem Flow dessen Durchlaufhistorie prüfen</td></tr><tr><td>Alles gilt sofort als bestätigt</td><td>Zuweisung ohne Häkchen <code>done</code> – ohne das Feld ist jede angelegte Zeile eine Bestätigung. Die App meldet die fehlenden Keys <code>done</code>/<code>editLink</code> in der Statuszeile</td></tr><tr><td>Bestätigt, nach dem Aktualisieren aber wieder offen</td><td><code>acknowledgements</code> fehlt, hat einen anderen Key, oder zeigt auf ein anderes Grid als das Formular</td></tr><tr><td>Nach dem Bestätigen zwei Zeilen zum selben Dokument</td><td>Zuweisung, aber <code>acknowledgeForm</code> steht noch im Dokument – Spalte leeren</td></tr><tr><td>Statuszeile „Kenntnisnahmen konnten nicht geladen werden“</td><td>Die Ansicht der Kenntnisnahmen ist nicht erreichbar, oder ihr fehlt <code>document</code>, „Erstellt von“ bzw. bei Zuweisung <code>done</code>/<code>editLink</code></td></tr><tr><td>Keine Frist im Hinweis</td><td>Das Datumsfeld hat keinen Key <code>acknowledgeUntil</code></td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/ansichten/ansicht-teilen">Ansicht teilen</a></li><li><a href="/formulare/formular-teilen">Formular teilen</a></li><li><a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></li><li><a href="/flows/router-und-parallel">Router und Parallel</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>`,68)])])}const m=t(r,[["render",a]]);export{g as __pageData,m as default};
